// ─── File: KRaftDemo.java ───
// Runnable demo: KRaft metadata quorum vs old ZooKeeper, fast failover.
package com.bank.kraft.demo;

import java.util.*;
import java.util.logging.*;

public class KRaftDemo {
    private static final Logger log = Logger.getLogger(KRaftDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // OLD WORLD: external ZooKeeper (for contrast)
        ZookeeperMetadataStore zk = new ZookeeperMetadataStore();
        zk.apply(new MetadataChange("CREATE_TOPIC", "transfers partitions=6 rf=3"));

        // NEW WORLD (Kafka 4.0): KRaft controller quorum of 3 (tolerates 1 failure)
        KRaftControllerQuorum quorum = new KRaftControllerQuorum("c1", "c2", "c3");
        MetadataService meta = new MetadataService(quorum);

        meta.applyChange(new MetadataChange("CREATE_TOPIC", "transfers partitions=6 rf=3"));
        meta.applyChange(new MetadataChange("ELECT_LEADER", "transfers-P0 leader=broker-1"));

        // Active controller crashes -> fast Raft re-election, metadata still available
        log.severe(() -> "Active controller c1 crashed");
        quorum.failController("c1");
        meta.applyChange(new MetadataChange("ELECT_LEADER", "transfers-P1 leader=broker-2"));
    }
}

// ─── Would be in MetadataChange.java ───
class MetadataChange {
    private final String type, detail;
        MetadataChange(String type, String detail) { this.type = type;
        this.detail = detail; }
    @Override public String toString() { return type + " [" + detail + "]"; }
}

// ─── Would be in ZookeeperMetadataStore.java (the OLD approach) ───
class ZookeeperMetadataStore {
    private static final Logger log = Logger.getLogger(ZookeeperMetadataStore.class.getName());
    void apply(MetadataChange change) {
        // Separate external system: extra hop, extra ops, scalability ceiling
        log.warning(() -> "ZOOKEEPER (legacy) applied " + change
                + " via external ensemble — slower, extra system to operate");
    }
}

// ─── Would be in KRaftControllerQuorum.java (the NEW approach) ───
class KRaftControllerQuorum {
    private static final Logger log = Logger.getLogger(KRaftControllerQuorum.class.getName());
    private final List<String> controllers = new ArrayList<>();
    private final List<MetadataChange> metadataLog = new ArrayList<>(); // __cluster_metadata
    private String activeController;
    KRaftControllerQuorum(String... controllers) {
        this.controllers.addAll(Arrays.asList(controllers));
        this.activeController = this.controllers.get(0);
    }
    int majority() { return controllers.size() / 2 + 1; }
    // Raft: committed once a MAJORITY of controllers replicate the change
    boolean replicate(MetadataChange change) {
        int acks = controllers.size(); // all live controllers copy it here
        if (acks >= majority()) {
            metadataLog.add(change);
            log.info(() -> "KRAFT committed " + change + " (acks=" + acks
                    + " >= majority=" + majority() + ") to __cluster_metadata");
            return true;
        }
        log.severe(() -> "KRAFT cannot commit " + change + " — no quorum");
        return false;
    }
    void failController(String id) {
        controllers.remove(id);
        if (id.equals(activeController)) {
            // Fast Raft election of a new active controller from survivors
            activeController = controllers.isEmpty() ? null : controllers.get(0);
            log.info(() -> "KRAFT fast re-election: new active controller=" + activeController);
        }
    }
    String getActiveController() { return activeController; }
}

// ─── Would be in MetadataService.java ───
class MetadataService {
    private static final Logger log = Logger.getLogger(MetadataService.class.getName());
    private final KRaftControllerQuorum quorum;
    MetadataService(KRaftControllerQuorum quorum) { this.quorum = quorum; }
    void applyChange(MetadataChange change) {
        boolean ok = quorum.replicate(change);
        log.info(() -> "Metadata change " + change + " -> "
                + (ok ? "AVAILABLE via controller " + quorum.getActiveController() : "UNAVAILABLE"));
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
